const t = (key, vars = {}) => Object.entries(vars).reduce((text, [name, value]) => text.replaceAll(`{${name}}`, value), messages[language]?.[key] || messages.zh[key] || key);
function applyLanguage() { document.documentElement.lang = language === 'zh' ? 'zh-CN' : language; updateMapEdges(); document.querySelectorAll('[data-i18n]').forEach(node => { node.textContent = t(node.dataset.i18n); }); document.querySelectorAll('[data-i18n-placeholder]').forEach(node => { node.placeholder = t(node.dataset.i18nPlaceholder); }); document.querySelectorAll('.language-select').forEach(select => { select.value = language; }); if (data) { renderRemembered(); renderCategories(); renderGuideControls(); render(); } }
const categoryPalette = ['#e96f43', '#2f7d69', '#d59b2d', '#6c67a9', '#3c78a8', '#b45b78', '#657d3e', '#9a6544', '#297e8d', '#8e6eaf', '#c47734', '#4f8275'];
const categoryColor = category => categoryPalette[Math.max(0, data?.categories?.indexOf(category) || 0) % categoryPalette.length];
function categoryMeta(category = '') { const rules = [
  [/咖啡/, '☕', '咖啡'], [/宁曼/, '🛵', '宁曼'], [/大自然|周边好玩/, '🌿', '自然'], [/落日/, '☀️', '落日'], [/宝藏好喝/, '🥤', '好喝'], [/Party/i, '🎉', '派对'], [/市集/, '🛍️', '市集'], [/自助餐|火锅/, '🍲', '自助'], [/酒吧/, '🍸', '酒吧'], [/温泉|spa/i, '♨️', '温泉'], [/碳水|泰餐/, '🍜', '泰餐'], [/Brunch|减脂/i, '🥗', '早午'], [/肉|蛋白质|中餐/, '🥩', '肉食'], [/巷子/, '🏘️', '巷里'], [/GYM|Fitness|按摩|Playing/i, '🏋️', '健身'], [/活动|Yuga/i, '🧘', '活动'], [/湄林|一小时/, '⛰️', '湄林'], [/Hostels/i, '🛏️', '青旅'], [/租车/, '🚗', '租车'], [/DJ/, '🎧', '音乐'], [/换汇/, '💱', '换汇'], [/财绅在哪里/, '📍', '财绅'], [/摩托维修/, '🔧', '修车'], [/紧急/, '🆘', '紧急'], [/手册/, '📖', '手册']
]; const match = rules.find(([pattern]) => pattern.test(category)); return match ? { icon: match[1], short: match[2] } : { icon: '✨', short: category.replace(/^[一二三四五六七八九十]+[，、.]?/, '').replace(/[|@&（(].*$/, '').trim().slice(0, 2) || '推荐' }; }
function stableNumber(value = '') { let hash = 2166136261; for (const char of String(value)) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619); return hash >>> 0; }
function clusterCenter(category) { const index = Math.max(0, data?.categories?.indexOf(category) || 0), ring = index < 1 ? 0 : index < 7 ? 1 : index < 19 ? 2 : 3, position = ring ? index - (ring === 1 ? 1 : ring === 2 ? 7 : 19) : 0, total = [1, 6, 12, 8][ring], angle = (position / total * Math.PI * 2) - Math.PI / 2, radius = [0, 2.05, 4.15, 6.1][ring]; return { lng: 101 + Math.cos(angle) * radius, lat: 14 + Math.sin(angle) * radius * .86 }; }
function displayLocation(item) { return item.location; } // 平面地图：所有地点落在真实经纬度上，不再使用球形聚簇偏移

async function api(url, options) { const response = await fetch(url, options); const body = await response.json().catch(() => ({})); if (!response.ok) throw Object.assign(new Error(body.error || '请求失败'), { status: response.status, retry: body.retryAfter }); return body; }
function remembered() { try { return JSON.parse(localStorage.getItem(rememberedKey) || '[]'); } catch { return []; } }
function rememberUser(user) { const list = remembered().filter(x => x.id !== user.id); list.unshift({ id: user.id, name: user.name }); localStorage.setItem(rememberedKey, JSON.stringify(list.slice(0, 8))); renderRemembered(); }
function renderRemembered() { const list = remembered(), select = $('#rememberedUsers'), input = $('#loginUser'); if (!list.length) { select.hidden = true; return; } select.hidden = false; select.innerHTML = `<option value="">${esc(t('remembered'))}</option>${list.map(x => `<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}<option value="__other">${esc(t('otherName'))}</option>`; select.onchange = () => { if (select.value === '__other') { input.value = ''; input.focus(); } else if (select.value) input.value = select.value; }; if (!input.value) { select.value = list[0].id; input.value = list[0].id; } }
function switchAuth(mode) { const register = mode === 'register'; $('#loginTab').classList.toggle('active', !register); $('#registerTab').classList.toggle('active', register); $('#loginForm').hidden = register; $('#registerForm').hidden = !register; }
async function boot() { renderRemembered(); try { const session = await api('/api/session'); currentUser = session.user; rememberUser(currentUser); await showApp(); } catch { $('#login').hidden = false; } }
function updateUserSummary() { $('#currentName').textContent = currentUser.name; $('#avatar').textContent = currentUser.name.slice(0, 1).toUpperCase(); $('#adminButton').hidden = !currentUser.admin; const remaining = Math.max(0, 6 - Math.floor(Number(currentUser.stars || 0) / 5)); $('#starSummary').innerHTML = `<strong>★ ${Number(currentUser.stars || 0)} ${esc(t('stars'))}</strong><span>${currentUser.coAdmin ? esc(t('coAdmin')) : esc(t('starsToAdmin', { count: remaining }))}</span>`; }
async function showApp() { $('#login').hidden = true; $('#app').hidden = false; initGuideBarSticky(); updateUserSummary(); data = await api('/api/places'); $('#updated').textContent = data.source.lastEdited ? `${t('updated')} ${new Date(data.source.lastEdited).toLocaleDateString(language === 'zh' ? 'zh-CN' : language)}` : ''; renderCategories(); renderGuideControls(); initGlobe(); render(); }

